import sys

def main():
    data = sys.stdin.read().split()
    n, m, t = int(data[0]), int(data[1]), int(data[2])
    indeg = [0] * n
    out = [[] for _ in range(n)]
    for i in range(m):
        a = int(data[3 + 2 * i]); b = int(data[4 + 2 * i])
        indeg[b] += 1
        out[a].append(b)
    treasure = [False] * n
    for x in data[3 + 2 * m: 3 + 2 * m + t]:
        treasure[int(x)] = True
    good = [False] * n
    for s in range(n):
        for v in out[s]:
            if treasure[v]:
                good[s] = True
                break
    res = []
    for r in range(n):
        if indeg[r] >= 2 and any(good[s] for s in out[r]):
            res.append(r)
    print(' '.join(map(str, res)) if res else -1)

